const productFormTabs=['Overview','Catalog','Commerce','Variants','Inventory','Logistics','Content','Internal','Suppliers'];
const productFormFields={
  Overview:[['Basic Information','Name *|Slug *|Product Type|Brand|Manufacturer|Model Number|Condition|Status|Storefront Status|Published Date|Online sale cap|Featured|Short Description|Long Description'],['Identifiers','SKU *|GTIN|UPC|EAN|ISBN|MPN|Barcode']],
  Catalog:[['Categorization','Category *|Subcategory|Collections|Tags'],['Relationships','Bundle Items|Related Products|Cross Sell Products|Upsell Products']],
  Commerce:[['Pricing','Price *|Sale Price|Compare-at Price|Cost Price|Currency|Tax Class|Subscription Price|Subscription Interval']],
  Logistics:[['Physical Attributes','Weight|Weight Unit|Length|Width|Height|Dimension Unit|Material|Color|Size|Pattern|Style|Capacity|Volume|Flavor|Scent|Gender|Age Group|Country of Origin'],['Shipping And Compliance','Requires Shipping|Free Shipping|Shipping Class|Shipping Cost|HS Code|Shipping Restrictions|Ingredients|Nutritional Information|Energy Rating|Warranty|Warranty Period|Hazard Classification|Production Date|Expiration Date|Return Policy|Safety Warnings|Compliance Certifications|Digital Download|Download URL|File Size|File Format|Download Limit|Download Expiry (days)|License Key']],
  Content:[['Media','Main Image URL|Image Alt Text|Video URL|3D Model URL|Image Gallery'],['Marketing And SEO','Meta Title|Canonical URL|Meta Description|Meta Keywords|SEO Keywords|Redirect URL|Release Date|Availability Date']],
  Internal:[['Customer And Internal Data','Rating|Review Count|Review Average|FAQ JSON|Custom Fields JSON|Notes|Internal Notes']]
};
const productFormOverrides={};
const productFormSelects={
  'Product Type':['Apparel','Accessory','Bundle','Service','Digital'],Condition:['New','Used','Refurbished'],Status:['Active','Inactive','Archived'],'Storefront Status':['Published','Draft','Scheduled','Offline','Archived'],Currency:['BDT','USD','EUR'],'Tax Class':['Standard','Reduced','Exempt'],'Subscription Interval':['None','Monthly','Yearly'],Category:['Shirts','Bags','T-Shirts','Sets','Bundles','Outerwear','Services'],Subcategory:['Casual','Everyday','Premium'], 'Weight Unit':['kg','g','lb'], 'Dimension Unit':['cm','in'], 'Shipping Class':['Standard','Oversize','Fragile']
};
const productFormTextareas=new Set(['Short Description','Long Description','Collections','Tags','Bundle Items','Related Products','Cross Sell Products','Upsell Products','Image Gallery','Meta Description','FAQ JSON','Custom Fields JSON','Notes','Internal Notes','Shipping Restrictions','Ingredients','Nutritional Information','Return Policy','Safety Warnings','Compliance Certifications']);
const productFormChecks=new Set(['Featured','Requires Shipping','Free Shipping','Digital Download']);
function productFormPath(path){const parts=path.split('/');const edit=parts[4]!=='new';const base=edit?parts.slice(0,6).join('/'):parts.slice(0,5).join('/');const tab=(edit?parts[6]:parts[5])||'overview';return {edit,base,tab,sku:edit?parts[4]:null,app:parts[2]};}
function productFormValue(label,product){if(!product)return '';const values={'Name *':product.name,'Slug *':product.name.toLowerCase().replace(/\s+/g,'-'),'Product Type':product.type,Brand:product.brand,Manufacturer:product.brand,Condition:'New',Status:product.status,'Storefront Status':product.online,'Online sale cap':product.stock,'Short Description':`A thoughtfully made ${product.name.toLowerCase()} for everyday use.`,'Long Description':`${product.name} is part of the curated Stravix assortment, designed for comfortable, reliable daily use.`,'SKU *':product.sku,'Category *':product.category,Collections:'Everyday Essentials',Tags:`${product.category}, ${product.brand}`,'Price *':product.price,'Cost Price':(product.price*.62).toFixed(2),Currency:'BDT','Tax Class':'Standard','Weight':'0.4','Weight Unit':'kg',Length:'32',Width:'24',Height:'3','Dimension Unit':'cm',Material:'Cotton',Color:'Sand','Country of Origin':'Bangladesh','HS Code':'6205.20','Meta Title':`${product.name} | Stravix Store`,'Meta Description':`Shop ${product.name} at Stravix Store.`,Rating:'4.8','Review Count':'24','Review Average':'4.8'};return values[label]??'';}
function productFormField(label,product,base){const id='pf-'+label.toLowerCase().replace(/[^a-z0-9]+/g,'-');const value=productFormOverrides[base+'|'+label]??productFormValue(label,product);const safe=esc(String(value));const required=label.endsWith('*');const choices=productFormSelects[label.replace(' *','')];let control;if(productFormChecks.has(label))control=`<label class="product-form-check"><input type="checkbox" data-pf-field="${esc(label)}" ${value||label==='Requires Shipping'?'checked':''}><span>Enabled</span></label>`;else if(choices)control=`<select id="${id}" data-pf-field="${esc(label)}"><option value="">Select ${esc(label.replace(' *','').toLowerCase())}</option>${choices.map(choice=>`<option ${choice===value?'selected':''}>${esc(choice)}</option>`).join('')}</select>`;else if(productFormTextareas.has(label))control=`<textarea id="${id}" data-pf-field="${esc(label)}" rows="3" placeholder="Enter ${esc(label.toLowerCase())}">${safe}</textarea>`;else control=`<input id="${id}" data-pf-field="${esc(label)}" type="${/Date$|Date \*/.test(label)?'date':/Price|Cost|cap|Weight|Length|Width|Height|Count|Average|Rating|Limit|Expiry/.test(label)?'number':'text'}" value="${safe}" placeholder="Enter ${esc(label.replace(' *','').toLowerCase())}" ${required?'required':''}>`;return `<div class="product-form-field"><label for="${id}">${esc(label)}</label>${control}</div>`;}
function productFormSection(title,labels,product,base){return `<section class="product-form-section"><div class="product-form-section-title"><h2>${esc(title)}</h2><span>${labels.length} fields</span></div><div class="product-form-grid">${labels.map(label=>productFormField(label,product,base)).join('')}</div></section>`;}
function productFormSpecial(tab,product,base){if(tab==='Inventory'){const quantity=product?.stock??0;return `<section class="product-form-section"><div class="product-form-section-title"><h2>Inventory Summary</h2><span>Inventory Module</span></div><div class="product-form-special"><h3>Warehouse and branch stock for this product</h3><p>Product edit no longer changes live stock directly. Use the Inventory module for adjustments, facility workflows, and stock history.</p><div class="product-form-stock"><div><span>Warehouse</span><strong>${Math.max(0,quantity-8)}</strong></div><div><span>Branches</span><strong>${Math.min(8,quantity)}</strong></div><div><span>Total Across Locations</span><strong>${quantity}</strong></div></div><div class="product-form-inline-actions"><a class="btn" href="#/app/inventory/adjustments">Open Adjustments</a><a class="btn" href="#/app/inventory/workspace">Open Inventory Workspace</a></div></div></section>`;}
if(tab==='Variants')return `<section class="product-form-section"><div class="product-form-section-title"><h2>Variants</h2><button class="btn" data-pf-action="variant">+ Create Variant</button></div><div class="product-form-special"><h3>Product-level variant configuration</h3><p>Define options and SKU attributes here. Location stock remains in Inventory.</p><div class="product-form-grid">${productFormField('Has Variants',product,base)}${productFormField('Variant Attributes',product,base)}</div><div class="product-form-rows"><div><strong>${product?.sku||'NEW'}-S</strong><span>Sand / Small</span><span>Active</span><button data-pf-action="variant">Edit</button></div><div><strong>${product?.sku||'NEW'}-M</strong><span>Sand / Medium</span><span>Active</span><button data-pf-action="variant">Edit</button></div></div></div></section>`;
if(tab==='Suppliers')return `<section class="product-form-section"><div class="product-form-section-title"><h2>Product Suppliers</h2><button class="btn" data-pf-action="supplier">+ Add Supplier Link</button></div><div class="product-form-special"><p>Maintain procurement relationships and preferred supplier information for this product.</p><div class="product-form-rows"><div><strong>Harbor Textiles Ltd.</strong><span>SUP-${product?.sku||'NEW'} · BDT ${(product?.price*.62||0).toFixed(2)}</span><span>Primary · Active</span><button data-pf-action="supplier">Edit</button></div></div></div></section>`;
return '';}
function renderCatalogProductForm(path){const {edit,base,tab,sku,app}=productFormPath(path);const product=catalogProducts.find(item=>item.sku===sku);const title=edit?'Edit Product':'Create Product';const current=productFormTabs.find(item=>item.toLowerCase()===tab)||'Overview';const tabs=productFormTabs.filter(item=>edit||!['Variants','Suppliers'].includes(item));const sections=productFormFields[current]||[];const price=product?.price??0;return `<div class="catalog-product-form"><header class="product-form-hero"><div><a class="product-form-back" href="#/app/${app}/products">← Back to Products</a><span class="eyebrow">PRODUCT WORKSPACE</span><h1>${title}</h1><p>Catalog editing owns product definition here, while the Inventory module owns live on-hand stock and facility balances.</p><div class="product-form-tags"><span>${product?.type||'No type'}</span><span>${product?.status||'active'}</span><span>${product?.online||'Draft'}</span></div></div><div class="product-form-hero-side"><div><strong>${edit?'7':'2'}/8</strong><span>Core fields ready</span></div><div><strong>BDT ${price.toFixed(2)}</strong><span>Current price</span></div></div></header><div class="product-form-layout"><div class="product-form-main"><div class="product-form-progress"><span>Section Progress</span><div><i style="width:${edit?'88':'25'}%"></i></div></div><nav class="product-form-tabs" aria-label="Product sections">${tabs.map(item=>`<a href="#${base}/${item.toLowerCase()}" class="${item===current?'active':''}" ${item===current?'aria-current="page"':''}>${item}</a>`).join('')}</nav>${sections.map(([heading,fields])=>productFormSection(heading,fields.split('|'),product,base)).join('')||productFormSpecial(current,product,base)}<footer class="product-form-actions"><button class="btn primary" data-pf-action="save">${edit?'Update Product':'Create Product'}</button><a class="btn" href="#/app/${app}/products">Cancel</a>${edit?'<button class="btn product-form-danger" data-pf-action="delete">Delete</button>':''}</footer></div><aside class="product-form-aside"><section class="product-form-snapshot"><span>SNAPSHOT</span><strong>${product?.category||'No category'}</strong><p>${product?.name||'New product'}</p><div><span>inventory tracked</span><span>${product?.online||'Draft'}</span></div></section><section class="product-form-sidecard"><h2>Important Hints</h2><ul><li>Keep slug lowercase and hyphenated.</li><li>SKU should remain unique across active and archived products.</li><li>Choose top-level category first, then subcategory.</li><li>Use compare_at_price only for an original crossed-out price.</li><li>Bulk pricing, FAQ, and custom fields accept JSON.</li></ul></section><section class="product-form-sidecard"><h2>System Metadata</h2><dl><div><dt>ID</dt><dd>${sku||'New product'}</dd></div><div><dt>Created</dt><dd>${edit?'18 Sep 2026':'—'}</dd></div><div><dt>Updated</dt><dd>${product?.updated||'—'}</dd></div><div><dt>Published</dt><dd>${product?.online==='Published'?'22 Sep 2026':'—'}</dd></div><div><dt>Deleted</dt><dd>—</dd></div></dl></section></aside></div></div>`;}
root.addEventListener('input',event=>{const field=event.target.dataset.pfField;if(!field)return;productFormOverrides[productFormPath(pathOf()).base+'|'+field]=event.target.type==='checkbox'?event.target.checked:event.target.value;});
root.addEventListener('click',event=>{const action=event.target.closest('[data-pf-action]')?.dataset.pfAction;if(!action)return;if(action==='save-overlay'){drawer='';flash('Sample link saved.');return;}if(action==='save'){const {base,edit,app,sku}=productFormPath(pathOf());const name=productFormOverrides[base+'|Name *']||catalogProducts.find(item=>item.sku===sku)?.name;if(!name){location.hash='#'+base+'/overview';flash('Enter a product name in Overview to continue.');return;}flash(edit?'Sample product changes saved.':'Sample product created.');return;}if(action==='delete'){flash('Delete preview: this sample product remains available for review.');return;}activeAction=action==='variant'?'Create or edit variant':'Add or edit supplier link';activeOverlayClass='product-form-drawer';const labels=action==='variant'?['Variant SKU *','Price Override','Tax Class','Main Image URL','Image Alt Text','Image Gallery','Active','Color','Size']:['Supplier *','Supplier SKU','Supplier Product Name','Cost','Currency','MOQ','Lead Time (days)','Priority Rank','Status','Primary Supplier'];activeOverlayHTML=`<div class="product-form-drawer-content"><p>Sample ${action} details for UX review.</p>${labels.map(label=>productFormField(label,null,'overlay')).join('')}<button class="btn primary" data-pf-action="save-overlay">Save ${action==='variant'?'Variant':'Supplier Link'}</button></div>`;drawer='original';render();});
